const text = $input.first().json.text || '';
const get = (key) => {
  const m = text.match(new RegExp('^' + key + ':\\s*(.+)$', 'mi'));
  return m ? m[1].trim() : '';
};
const alert = $('Webhook').first().json.body || {};
const level = Number(alert?.rule?.level) || 0;

// 1) What the model said
let aiSeverity = get('SEVERITY').toLowerCase();
if (!['low', 'medium', 'high'].includes(aiSeverity)) aiSeverity = 'unknown';

// 2) Checks that do not depend on the model: prompt-injection patterns in
//    the fields an attacker can control (alert data and full_log)
const strings = [];
const walk = (v) => {
  if (typeof v === 'string') strings.push(v);
  else if (v && typeof v === 'object') Object.values(v).forEach(walk);
};
walk(alert.data);
walk(alert.full_log);

const formatSpoof = /^\s*(SEVERITY|CATEGORY|SUMMARY|LIKELY_FALSE_POSITIVE|RECOMMENDED_ACTION)\s*:/im;
const phrases = /ignore (all )?(the )?(previous|above)|system note|disregard|new instructions|you are now/i;
const injectionSuspected = strings.some((s) => formatSpoof.test(s) || phrases.test(s));

// 3) The model may not hide a serious or suspicious alert
let severity = aiSeverity;
const overridden = severity === 'low' && (injectionSuspected || level >= 10);
if (overridden) severity = 'medium';

return [{
  json: {
    severity,
    severity_ai: aiSeverity,
    overridden,
    injection_suspected: injectionSuspected,
    ai_ok: text.length > 0,
    category: get('CATEGORY') || 'AI triage unavailable',
    summary: get('SUMMARY') || 'AI triage failed. Review the original alert manually.',
    false_positive: get('LIKELY_FALSE_POSITIVE') || 'unknown',
    action: get('RECOMMENDED_ACTION') || 'Review the alert in the Wazuh dashboard.',
    agent: alert?.agent?.name || '',
    rule_id: alert?.rule?.id || '',
    rule_level: alert?.rule?.level || 0,
    rule_description: alert?.rule?.description || ''
  }
}];

